//! C API for an Apple Network Extension (header: `include/maski.h`, generated by cbindgen).
//!
//! Rust owns the outer UDP sockets and the QUIC/HTTP-3 state on its own thread (a single-threaded
//! tokio runtime). The extension supplies the configuration, the inner packets (either the utun
//! file descriptor behind `packetFlow`, or packets passed in/out through calls and a callback),
//! and network-change notifications from `NWPathMonitor`.
//!
//! Lifecycle: `maski_start` returns at once; `MASKI_EVENT_CONNECTED` (with the assigned address as JSON)
//! arrives on the runtime thread when the tunnel is up, `MASKI_EVENT_FAILED` if it could not connect,
//! `MASKI_EVENT_STOPPED` after `maski_stop`. All functions are thread-safe; callbacks run on the
//! runtime thread and must not block.

use std::ffi::{c_char, c_void, CStr, CString};
use std::sync::{Arc, Mutex};

use serde::Deserialize;

use crate::client::{self, ClientOpts, PacketOut};
use crate::net::{DcidMode, QuicTuning};

pub const MASKI_EVENT_CONNECTED: i32 = 1;
pub const MASKI_EVENT_FAILED: i32 = 2;
pub const MASKI_EVENT_STOPPED: i32 = 3;
/// The client moved the connection to another interface by itself (fallback / return):
/// {"from","to","why","silent_ms"}, `why` = unreachable | silent | failed_return | probe | alt_gone.
pub const MASKI_EVENT_PATH: i32 = 4;

/// Packets from the server: `count` packets, `pkts[i]` of `lens[i]` bytes, valid only during the
/// call (copy them, e.g. into `NEPacketTunnelFlow.writePackets`).
pub type MaskiPacketsFn = Option<extern "C" fn(ctx: *mut c_void, pkts: *const *const u8, lens: *const usize, count: usize)>;
/// Lifecycle events; `json` is a NUL-terminated UTF-8 JSON object, valid only during the call.
pub type MaskiEventFn = Option<extern "C" fn(ctx: *mut c_void, kind: i32, json: *const c_char)>;

/// Log lines (`maski_set_log`): `line` is NUL-terminated UTF-8 without a trailing newline.
pub type MaskiLogFn = Option<extern "C" fn(level: i32, line: *const c_char)>;

/// Snapshot of the client's counters (`maski_stats`).
#[repr(C)]
#[derive(Default)]
pub struct MaskiStats {
    pub connected: bool,
    pub generation: u64,
    pub tx_packets: u64,
    pub tx_bytes: u64,
    pub rx_packets: u64,
    pub rx_bytes: u64,
    pub migrations: u64,
    pub reconnects: u64,
    pub dropped: u64,
    pub too_large: u64,
    pub rtt_us: u64,
    pub path_mtu: u16,
    pub lost_packets: u64,
    pub udp_tx_bytes: u64,
    pub udp_rx_bytes: u64,
    pub silent_ms: u64,
    // Added after the first app build; new fields go at the end.
    pub sent_packets: u64,
    pub sock_nobufs: u64,
    pub sock_errors: u64,
    pub sock_blocked: u64,
    pub queue_drops: u64,
    pub bw_bps: u64,
    pub cwnd: u64,
    // Interface fallback (maski_set_alternates).
    pub fallbacks: u64,
    pub fb_returns: u64,
    pub fb_probes: u64,
    pub fb_probe_fails: u64,
    pub on_alternate: bool,
}

/// Configuration (JSON). Defaults are the phone settings measured on the mobile network.
#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct Config {
    server: String,
    #[serde(default = "d_sni")]
    sni: String,
    pin: String,
    user: String,
    pass: String,
    #[serde(default = "d_path")]
    path: String,
    /// Interface to pin outer sockets to (e.g. "pdp_ip0", "en0"); none = OS choice.
    #[serde(default)]
    interface: Option<String>,
    #[serde(default = "d_keepalive")]
    keepalive_ms: u64,
    #[serde(default = "d_dead")]
    dead_ms: u64,
    #[serde(default = "d_remigrate")]
    remigrate_ms: u64,
    #[serde(default = "d_recover")]
    recover: String,
    #[serde(default = "d_attempt")]
    attempt_ms: u64,
    /// See `ClientOpts::race_ms` (0 = off).
    #[serde(default = "d_race")]
    race_ms: u64,
    #[serde(default = "d_idle")]
    idle_timeout_ms: u64,
    #[serde(default = "d_mtu")]
    initial_mtu: u16,
    #[serde(default = "d_mtu")]
    min_mtu: u16,
    #[serde(default = "d_mtu_upper")]
    mtu_upper: u16,
    #[serde(default = "d_cc")]
    cc: String,
    #[serde(default = "d_queue_ms")]
    queue_ms: u64,
    #[serde(default = "d_dgram_rcvbuf")]
    dgram_rcvbuf: usize,
    #[serde(default = "d_dgram_sndbuf")]
    dgram_sndbuf: usize,
    #[serde(default = "d_sockbuf")]
    sockbuf: usize,
    #[serde(default = "d_dcid")]
    initial_dcid: String,
    /// Open migration sockets with a short throw-away datagram (see `net::send_primer`).
    #[serde(default = "d_true")]
    primer: bool,
    /// MTU of the inner packets (TUN mode only: the utun device's MTU).
    #[serde(default = "d_tun_mtu")]
    tun_mtu: u16,
}

fn d_sni() -> String { "www.example.com".into() }
fn d_path() -> String { "/.well-known/masque/ip/*/*/".into() }
fn d_keepalive() -> u64 { 500 }
fn d_dead() -> u64 { 1500 }
fn d_remigrate() -> u64 { 200 }
fn d_recover() -> String { "migrate".into() }
fn d_attempt() -> u64 { 1000 }
fn d_race() -> u64 { 5000 }
fn d_idle() -> u64 { 30000 }
fn d_mtu() -> u16 { 1400 }
fn d_mtu_upper() -> u16 { 1432 }
fn d_cc() -> String { "rate".into() }
fn d_queue_ms() -> u64 { 30 }
fn d_dgram_rcvbuf() -> usize { 1024 * 1024 }
fn d_dgram_sndbuf() -> usize { 512 * 1024 }
fn d_sockbuf() -> usize { 2 * 1024 * 1024 }
fn d_dcid() -> String { "low".into() }
fn d_tun_mtu() -> u16 { 1360 }
fn d_true() -> bool { true }

impl Config {
    fn opts(self) -> anyhow::Result<(ClientOpts, u16)> {
        let tuning = QuicTuning {
            cc: self.cc,
            initial_mtu: self.initial_mtu,
            min_mtu: self.min_mtu,
            mtu_upper: self.mtu_upper,
            dgram_sndbuf: self.dgram_sndbuf,
            dgram_rcvbuf: self.dgram_rcvbuf,
            sockbuf: self.sockbuf,
            keepalive_ms: self.keepalive_ms,
            idle_timeout_ms: self.idle_timeout_ms,
            gso: false,
            ack_threshold: None,
            initial_rtt_ms: 333,
            dcid: self.initial_dcid.parse::<DcidMode>()?,
            queue_ms: self.queue_ms,
        };
        Ok((ClientOpts {
            server: self.server.parse()?,
            sni: self.sni,
            interface: self.interface,
            pin: self.pin,
            user: self.user,
            pass: self.pass,
            path: self.path,
            tuning,
            dead_ms: self.dead_ms,
            stats_secs: 0,
            send_wait: false,
            recover: self.recover,
            attempt_ms: self.attempt_ms,
            remigrate_ms: self.remigrate_ms,
            first_attempts: 30,
            primer: self.primer,
            alternates: vec![],
            race_ms: self.race_ms,
        }, self.tun_mtu))
    }
}

#[derive(Clone, Copy)]
struct Ctx(*mut c_void);
// The context pointer is owned by the caller, who promises it stays valid until STOPPED.
unsafe impl Send for Ctx {}
unsafe impl Sync for Ctx {}

impl Ctx {
    // A method (not a field access) so closures capture the whole Send+Sync wrapper.
    fn ptr(self) -> *mut c_void {
        self.0
    }
}

/// Opaque handle returned by `maski_start`.
pub struct MaskiHandle {
    client: Arc<Mutex<Option<client::Handle>>>,
    stop: Mutex<Option<tokio::sync::oneshot::Sender<()>>>,
    thread: Mutex<Option<std::thread::JoinHandle<()>>>,
}

fn emit(ev: MaskiEventFn, ctx: Ctx, kind: i32, json: String) {
    if let Some(f) = ev {
        let s = CString::new(json).unwrap_or_default();
        f(ctx.ptr(), kind, s.as_ptr());
    }
}

fn json_str(s: &str) -> String {
    let mut o = String::from("\"");
    for ch in s.chars() {
        match ch {
            '"' => o.push_str("\\\""),
            '\\' => o.push_str("\\\\"),
            c if (c as u32) < 0x20 => o.push_str(&format!("\\u{:04x}", c as u32)),
            c => o.push(c),
        }
    }
    o.push('"');
    o
}

/// Start the client. `config_json`: see the crate docs / `Config`. `tun_fd` >= 0: Rust reads and
/// writes that utun descriptor itself and `packets` is unused; `tun_fd` < 0: packets from the
/// server go to `packets`, packets to the server come in through `maski_send_packets`.
/// Returns NULL if the configuration is invalid (an `MASKI_EVENT_FAILED` carries the reason).
///
/// # Safety
/// `config_json` must be a valid NUL-terminated string; `ctx` must stay valid until `maski_stop`
/// returns (or, if this returns NULL, until it returns). `MASKI_EVENT_STOPPED` is always the last
/// event of a started client, also after `MASKI_EVENT_FAILED`.
#[no_mangle]
pub unsafe extern "C" fn maski_start(config_json: *const c_char, tun_fd: i32, packets: MaskiPacketsFn, events: MaskiEventFn,
    ctx: *mut c_void) -> *mut MaskiHandle {
    let ctx = Ctx(ctx);
    let cfg = (!config_json.is_null())
        .then(|| unsafe { CStr::from_ptr(config_json) }.to_str().ok())
        .flatten()
        .ok_or_else(|| anyhow::anyhow!("config is not UTF-8"))
        .and_then(|s| Ok(serde_json::from_str::<Config>(s)?))
        .and_then(Config::opts);
    let (opts, tun_mtu) = match cfg {
        Ok(x) => x,
        Err(e) => {
            emit(events, ctx, MASKI_EVENT_FAILED, format!("{{\"error\":{}}}", json_str(&format!("{e:#}"))));
            return std::ptr::null_mut();
        }
    };
    let client: Arc<Mutex<Option<client::Handle>>> = Arc::new(Mutex::new(None));
    let (stop_tx, stop_rx) = tokio::sync::oneshot::channel::<()>();
    let slot = client.clone();
    let slot2 = client.clone();
    let thread = std::thread::Builder::new().name("maski".into()).stack_size(512 * 1024).spawn(move || {
        let ctx = ctx;
        let rt = match tokio::runtime::Builder::new_current_thread().enable_all().build() {
            Ok(rt) => rt,
            Err(e) => {
                emit(events, ctx, MASKI_EVENT_FAILED, format!("{{\"error\":{}}}", json_str(&e.to_string())));
                return;
            }
        };
        rt.block_on(async move {
            let mut stop_rx = stop_rx;
            let h = tokio::select! {
                r = client::start(opts) => match r {
                    Ok(h) => h,
                    Err(e) => {
                        emit(events, ctx, MASKI_EVENT_FAILED, format!("{{\"error\":{}}}", json_str(&format!("{e:#}"))));
                        return;
                    }
                },
                _ = &mut stop_rx => return,
            };
            if tun_fd >= 0 {
                match crate::tunio::from_fd(tun_fd, tun_mtu) {
                    Ok(dev) => {
                        let dev = Arc::new(dev);
                        h.set_output(Some(PacketOut::Tun(dev.clone())));
                        tokio::spawn(client::pump_tun(h.clone(), dev));
                    }
                    Err(e) => {
                        h.stop();
                        emit(events, ctx, MASKI_EVENT_FAILED, format!("{{\"error\":{}}}", json_str(&format!("{e:#}"))));
                        return;
                    }
                }
            } else if let Some(f) = packets {
                h.set_output(Some(PacketOut::Callback(Arc::new(move |pkts: &[&[u8]]| {
                    let ptrs: Vec<*const u8> = pkts.iter().map(|p| p.as_ptr()).collect();
                    let lens: Vec<usize> = pkts.iter().map(|p| p.len()).collect();
                    f(ctx.ptr(), ptrs.as_ptr(), lens.as_ptr(), pkts.len());
                }))));
            }
            h.set_event_sink(Some(Arc::new(move |json: String| emit(events, ctx, MASKI_EVENT_PATH, json))));
            *slot.lock().unwrap() = Some(h.clone());
            let (attempts, ms) = h.first_connect();
            emit(events, ctx, MASKI_EVENT_CONNECTED, format!("{{\"address\":\"{}\",\"max_packet\":{},\"attempts\":{attempts},\"connect_ms\":{ms}}}",
                h.addr(), h.max_packet().unwrap_or(0)));
            let _ = stop_rx.await;
            h.stop();
            // Let the CONNECTION_CLOSE go out.
            tokio::time::sleep(std::time::Duration::from_millis(50)).await;
        });
        *slot2.lock().unwrap() = None;
        drop(rt);
        emit(events, ctx, MASKI_EVENT_STOPPED, "{}".into());
    });
    match thread {
        Ok(t) => Box::into_raw(Box::new(MaskiHandle { client, stop: Mutex::new(Some(stop_tx)), thread: Mutex::new(Some(t)) })),
        Err(e) => {
            emit(events, ctx, MASKI_EVENT_FAILED, format!("{{\"error\":{}}}", json_str(&e.to_string())));
            std::ptr::null_mut()
        }
    }
}

fn with_client<R>(h: *const MaskiHandle, f: impl FnOnce(&client::Handle) -> R) -> Option<R> {
    let h = unsafe { h.as_ref()? };
    let c = h.client.lock().unwrap().clone()?;
    Some(f(&c))
}

/// Send IP packets to the server (callback mode). Returns how many were accepted (0 before
/// `MASKI_EVENT_CONNECTED`).
///
/// # Safety
/// `pkts`/`lens` must point to `count` valid entries.
#[no_mangle]
pub unsafe extern "C" fn maski_send_packets(h: *const MaskiHandle, pkts: *const *const u8, lens: *const usize, count: usize) -> usize {
    if pkts.is_null() || lens.is_null() {
        return 0;
    }
    with_client(h, |c| {
        let (p, l) = unsafe { (std::slice::from_raw_parts(pkts, count), std::slice::from_raw_parts(lens, count)) };
        for i in 0..count {
            c.send_packet(unsafe { std::slice::from_raw_parts(p[i], l[i]) });
        }
        count
    })
    .unwrap_or(0)
}

/// The network path changed (NWPathMonitor): move to a fresh socket pinned to `interface`
/// (NULL = keep the current pin, "" = unpinned) and restart path-failure detection.
///
/// # Safety
/// `interface` must be NULL or a valid NUL-terminated string.
#[no_mangle]
pub unsafe extern "C" fn maski_network_changed(h: *const MaskiHandle, interface: *const c_char) {
    let iface = (!interface.is_null()).then(|| unsafe { CStr::from_ptr(interface) }.to_string_lossy().into_owned());
    with_client(h, |c| c.network_changed(iface.as_deref()));
}

/// Other usable interfaces to fall back to when the pinned one is dead, comma-separated
/// ("pdp_ip0"); "" or NULL = no fallback (the default). Call again whenever the set changes
/// (only usable, unconstrained interfaces belong here). Ignored before MASKI_EVENT_CONNECTED.
///
/// # Safety
/// `csv` must be NULL or a valid NUL-terminated string.
#[no_mangle]
pub unsafe extern "C" fn maski_set_alternates(h: *const MaskiHandle, csv: *const c_char) {
    let s = (!csv.is_null()).then(|| unsafe { CStr::from_ptr(csv) }.to_string_lossy().into_owned()).unwrap_or_default();
    let list: Vec<String> = s.split(',').map(|x| x.trim().to_string()).filter(|x| !x.is_empty()).collect();
    with_client(h, |c| c.set_alternates(&list));
}

/// TEST HOOK (test drivers only): black-hole every socket on `interface` (NULL = the current pin),
/// present and future. mode 0 = off, 1 = drop all traffic silently ("Wi-Fi associated but dead"),
/// 2 = sends fail as unreachable.
///
/// # Safety
/// `interface` must be NULL or a valid NUL-terminated string.
#[no_mangle]
pub unsafe extern "C" fn maski_test_blackhole(h: *const MaskiHandle, interface: *const c_char, mode: i32) {
    let iface = (!interface.is_null()).then(|| unsafe { CStr::from_ptr(interface) }.to_string_lossy().into_owned());
    with_client(h, |c| c.test_blackhole(iface.as_deref(), mode.clamp(0, 2) as u8));
}

/// Fill `out` with the current counters; false if not connected yet.
///
/// # Safety
/// `out` must be valid for writes.
#[no_mangle]
pub unsafe extern "C" fn maski_stats(h: *const MaskiHandle, out: *mut MaskiStats) -> bool {
    let Some(out) = (unsafe { out.as_mut() }) else { return false };
    with_client(h, |c| {
        let s = c.stats();
        *out = MaskiStats {
            connected: s.connected, generation: s.gen, tx_packets: s.tx_pkts, tx_bytes: s.tx_bytes, rx_packets: s.rx_pkts,
            rx_bytes: s.rx_bytes, migrations: s.migrations, reconnects: s.reconnects, dropped: s.dropped, too_large: s.too_large,
            rtt_us: s.rtt_us, path_mtu: s.path_mtu, lost_packets: s.lost_pkts, udp_tx_bytes: s.udp_tx_bytes,
            udp_rx_bytes: s.udp_rx_bytes, silent_ms: s.silent_ms, sent_packets: s.sent_pkts, sock_nobufs: s.sock_nobufs,
            sock_errors: s.sock_errors, sock_blocked: s.sock_blocked, queue_drops: s.queue_drops, bw_bps: s.bw_bps,
            cwnd: s.cwnd, fallbacks: s.fallbacks, fb_returns: s.returns, fb_probes: s.probes, fb_probe_fails: s.probe_fails,
            on_alternate: s.on_alternate,
        };
        true
    })
    .unwrap_or(false)
}

/// Stop the client, wait for its thread to finish (after `MASKI_EVENT_STOPPED`) and free the handle.
///
/// # Safety
/// `h` must come from `maski_start` and not be used afterwards.
#[no_mangle]
pub unsafe extern "C" fn maski_stop(h: *mut MaskiHandle) {
    if h.is_null() {
        return;
    }
    let h = unsafe { Box::from_raw(h) };
    if let Some(tx) = h.stop.lock().unwrap().take() {
        let _ = tx.send(());
    }
    let t = h.thread.lock().unwrap().take();
    if let Some(t) = t {
        let _ = t.join();
    }
}

struct LogWriter(extern "C" fn(i32, *const c_char), i32);

impl std::io::Write for LogWriter {
    fn write(&mut self, buf: &[u8]) -> std::io::Result<usize> {
        let line = String::from_utf8_lossy(buf);
        if let Ok(c) = CString::new(line.trim_end().replace('\0', " ")) {
            (self.0)(self.1, c.as_ptr());
        }
        Ok(buf.len())
    }
    fn flush(&mut self) -> std::io::Result<()> {
        Ok(())
    }
}

/// Route the library's log to `cb` (e.g. os_log). `level`: 1 error, 2 warn, 3 info, 4 debug.
/// Call once, before `maski_start`; later calls are ignored.
#[no_mangle]
pub extern "C" fn maski_set_log(cb: MaskiLogFn, level: i32) {
    let Some(cb) = cb else { return };
    let max = match level {
        i32::MIN..=1 => tracing::Level::ERROR,
        2 => tracing::Level::WARN,
        3 => tracing::Level::INFO,
        _ => tracing::Level::DEBUG,
    };
    let _ = tracing_subscriber::fmt()
        .with_ansi(false)
        .without_time()
        .with_max_level(max)
        .with_writer(move || LogWriter(cb, level))
        .try_init();
}
